mapper.select:
SELECT A.dataStatus , A.ASSET_UUID, A.ASSET_NAME, A.ASSET_CODE, trim(L.LINKED_ITEM_CODE) asset_type, A.ASSET_TYPE2, A.ORG_ASSET_TYPE1, A.ORG_ASSET_TYPE2, A.ORG_ASSET_TYPE3, A.vDateStr, A.mDateStr, A.ERRMSG
FROM ( SELECT i.STATUS dataStatus , i.ASSET_UUID, i.ASSET_NAME, i.ASSET_CODE, i.ASSET_TYPE, i.ASSET_TYPE2, i.ORG_ASSET_TYPE1, i.ORG_ASSET_TYPE2, i.ORG_ASSET_TYPE3, DATE_FORMAT(i.VDATE,'%Y-%m-%d') vDateStr, DATE_FORMAT(i.MDATE,'%Y-%m-%d') mDateStr, null ERRMSG FROM chb_asset_info i WHERE 1=1 and i.STATUS in ('E','D')
#{item}
#{item}
#{item}
#{item}
and i.STATUS = #{dataStatus}
AND ASSET_UUID = #{Assetuuid,jdbcType=VARCHAR}
and not exists ( SELECT 1 FROM CHB_ASSET_INFO_ERRODATA IE WHERE IE.ASSET_CODE = i.ASSET_CODE )
UNION ALL SELECT 'A' dataStatus, e.DATAUUID ASSET_UUID, e.ASSET_NAME, e.ASSET_CODE, e.ASSET_TYPE, e.ASSET_TYPE2, e.ORG_ASSET_TYPE1, e.ORG_ASSET_TYPE2, e.ORG_ASSET_TYPE3, e.VDATE vDateStr, e.MDATE mDateStr, e.ERR_MSG FROM CHB_ASSET_INFO_ERRODATA e WHERE 1=1 and e.STATUS in ('A')
#{item}
#{item}
#{item}
#{item}
and 1=2
AND DATAUUID = #{Assetuuid,jdbcType=VARCHAR}
) a left join SYS_DATADICT_LIST_LINK L ON L.LINKED_DICT_CODE = 'SVR_ASSET_TYPE_FIRST_LEVEL' AND L.ITEM_CODE = A.ASSET_TYPE2 WHERE 1=1
#{item}
ORDER BY A.dataStatus DESC

SELECT DISTINCT ASSET_CODE id, ASSET_NAME text from ( SELECT ASSET_CODE,ifnull(ASSET_NAME,ASSET_CODE) ASSET_NAME FROM CHB_ASSET_INFO ASSETINFO
1=1 and ASSETINFO.STATUS IN ('E','M')
and ASSETINFO.ASSET_CODE like concat(concat('%', #{search}),'%') or ASSETINFO.ASSET_NAME like concat(concat('%', #{search}),'%')
#{orgCode,jdbcType=VARCHAR}
union all
SELECT ASSET_CODE,ifnull(ASSET_NAME,ASSET_CODE) ASSET_NAME FROM CHB_ASSET_INFO_ERRODATA data
and data.ASSET_CODE like concat(concat('%', #{search}),'%') or data.ASSET_NAME like concat(concat('%', #{search}),'%')
#{orgCode,jdbcType=VARCHAR}
) t ORDER BY ASSET_CODE

SELECT DISTINCT COUNTER_ID id, COUNTER_NAME text from ( SELECT COUNTER_ID,COUNTER_NAME FROM CHB_MST_COUNTER_PARTY PARTY
1=1 and PARTY.STATUS IN ('E')
and PARTY.COUNTER_ID like concat(concat('%', #{search}),'%') or PARTY.COUNTER_NAME like concat(concat('%', #{search}),'%')
#{orgCode,jdbcType=VARCHAR}
) A ORDER BY COUNTER_NAME

SELECT *
FROM CHB_ASSET_INFO A
where ASSET_CODE = #{assetCode,jdbcType=VARCHAR}

SELECT * FROM SYS_DATADICT_LIST_LINK
WHERE 1=1

    and LINKED_DICT_CODE = #{linkDictCode}


    and LINKED_ITEM_CODE = #{linkItemCode}

