SELECT E.CHB_ASSET_TYPE2 id, l.ITEM_VALUE text
FROM CHB_ASSET_TYPE_MAPPING_EX E
left join CHB_ASSET_TYPE_MAPPING M ON E.MAPPING_UUID = M.TYPEUUID
LEFT JOIN SYS_DATADICT_LIST L ON L.DICT_CODE = 'SVR_ASSET_TYPE_SECOND_LEVEL' AND E.CHB_ASSET_TYPE2 = L.ITEM_CODE
WHERE
M.ASSET_TYPE1 = #{orgAssetType1}

    AND M.ASSET_TYPE2 =#{orgAssetType2}


    AND M.ASSET_TYPE3 =#{orgAssetType3}


    AND M.ASSET_BUSI_TYPE =#{orgAssetType4}


    AND (E.CHB_ASSET_TYPE2 like '%'|| #{search} ||'%'
